var PP_NEEDS_API = { NEXTMENU: NEXTMENU, ppNeedsFor: ppNeedsFor, ppNeedsForComps: ppNeedsForComps,
  ppMealComponents: ppMealComponents, ppPlannerToDish: ppPlannerToDish,
  ppTotals: ppTotals, ppRecipeFor: ppRecipeFor, ppNamedFoods: ppNamedFoods,
  PP_SHEET_UOM: PP_SHEET_UOM, gper: gper,
  dishCount: Object.keys(PP_NEEDS).length };
